696	// runNormalizeJSON works like runNormalize but decodes result lines with
697	// json.Number, so tests can assert that high-precision numbers in extra
698	// survive normalization verbatim instead of being rounded into float64.
699	func runNormalizeJSON(t *testing.T, input string) []map[string]any {
700		t.Helper()
701		var out bytes.Buffer
702		failures, err := NormalizeReader(strings.NewReader(input), &out)
703		if err != nil {
704			t.Fatalf("NormalizeReader returned error: %v", err)
705		}
706		results := []map[string]any{}
707		dec := json.NewDecoder(bytes.NewReader(out.Bytes()))
708		dec.UseNumber()
709		for {
710			var m map[string]any
711			if err := dec.Decode(&m); err != nil {
712				if err == io.EOF {
713					break
714				}
715				t.Fatalf("decoding result: %v", err)
716			}
717			results = append(results, m)
718		}
719		if got := countFailures(results); got != failures {
720			t.Fatalf("NormalizeReader returned %d failures but output shows %d", failures, got)
721		}
722		return results
723	}
