		`{"timestamp":"2026-01-02T00:00:00Z","action":"a","x":01}`,
		`{"timestamp":"2026-01-02T00:00:00Z","action":"a","x":+1}`,
		`{"timestamp":"2026-01-02T00:00:00Z","action":"a","x":1.}`,
		`{"timestamp":"2026-01-02T00:00:00Z","action":"a","x":{"nested":007}}`,
