187		if !ok || len(tags) != 2 || tags[0] != "a" || tags[1] != "b" {
188			t.Fatalf("extra arrays must keep their element order and types, got %#v", extra["tags"])
189		}
190		meta, ok := extra["meta"].(map[string]any)
191		if !ok || meta["trace"] != "t-1" {
192			t.Fatalf("extra objects must survive the command entry intact, got %#v", extra["meta"])
193		}
194	}
195	
196	// The key mixed-input case: a field-invalid log between two valid ones. The
197	// bad line gets an ok:false result with an explanatory error and no event,
198	// the surrounding valid lines still succeed in input order, and the process
199	// exits 1 — it must neither stop at the first bad line nor let the trailing
200	// success reset the status to 0. stderr stays empty because the failure is
201	// described by its own result record.
202	func TestNormalizeCLIInvalidLineBetweenValidOnesExitsOne(t *testing.T) {
203		input := `{"timestamp":"2026-01-02T00:00:00Z","action":"first"}` + "\n" +
204			`{"timestamp":"not-a-time","action":"broken"}` + "\n" +
205			`{"timestamp":"2026-01-02T00:00:02Z","action":"last"}` + "\n"
206	
207		result := runNormalizeCLI(t, strings.NewReader(input))
208	
209		if result.exitCode != 1 {
210			t.Fatalf("one invalid log must set exit status 1, got %d (stderr: %q)", result.exitCode, result.stderr)
211		}
212		if result.stderr != "" {
213			t.Fatalf("per-line failures belong in result records, not stderr, got %q", result.stderr)
214		}
215	
216		results := decodeStdoutResults(t, result.stdout)
217		if len(results) != 3 {
218			t.Fatalf("processing must continue past the bad line; expected 3 results, got %#v", results)
219		}
220	
221		if results[0]["line"] != float64(1) || results[0]["ok"] != true {
222			t.Fatalf("the leading valid log must succeed on line 1: %#v", results[0])
223		}
224		if eventOf(t, results[0])["action"] != "first" {
225			t.Fatalf("line 1 event content mismatch: %#v", results[0])
226		}
227	
228		bad := results[1]
229		if bad["line"] != float64(2) || bad["ok"] != false {
230			t.Fatalf("the invalid log must be reported as line 2 with ok=false: %#v", bad)
231		}
232		if _, exists := bad["event"]; exists {
233			t.Fatalf("a failed line must not carry an event: %#v", bad)
234		}
235		message, ok := bad["error"].(string)
236		if !ok || message == "" {
237			t.Fatalf("a failed line must explain itself in error: %#v", bad)
238		}
239		if !strings.Contains(message, "timestamp") {
240			t.Fatalf("the error must name the offending field, got %q", message)
241		}
242	
243		if results[2]["line"] != float64(3) || results[2]["ok"] != true {
244			t.Fatalf("the trailing valid log must still succeed on line 3: %#v", results[2])
245		}
246		if eventOf(t, results[2])["action"] != "last" {
247			t.Fatalf("line 3 event content mismatch: %#v", results[2])
248		}
249	}
250	
251	// Blank lines produce no results but still consume physical line numbers,
252	// and a final complete log without a trailing newline is processed like any
253	// other. The run is clean, so the exit status is 0 and stderr stays empty.
254	func TestNormalizeCLIBlankLinesAndMissingFinalNewline(t *testing.T) {
255		input := "\n" +
256			"   \n" +
257			`{"timestamp":"2026-01-02T00:00:00Z","action":"alpha"}` + "\n" +
258			"\t\n" +
259			`{"timestamp":"2026-01-02T00:00:01Z","action":"omega"}` // no trailing newline
260	
261		result := runNormalizeCLI(t, strings.NewReader(input))
262	
263		if result.exitCode != 0 {
264			t.Fatalf("blank lines and a newline-less tail must exit 0, got %d (stderr: %q)", result.exitCode, result.stderr)
265		}
266		if result.stderr != "" {
267			t.Fatalf("a clean run must not write to stderr, got %q", result.stderr)
268		}
269	
270		results := decodeStdoutResults(t, result.stdout)
271		if len(results) != 2 {
272			t.Fatalf("blank lines must not produce results, got %#v", results)
273		}
274		if results[0]["line"] != float64(3) {
275			t.Fatalf("line numbers must count blank physical lines, got %#v", results[0])
276		}
277		if results[0]["ok"] != true || eventOf(t, results[0])["action"] != "alpha" {
278			t.Fatalf("line 3 result mismatch: %#v", results[0])
279		}
280		if results[1]["line"] != float64(5) {
281			t.Fatalf("the final log must keep its physical line number 5, got %#v", results[1])
282		}
283		if results[1]["ok"] != true || eventOf(t, results[1])["action"] != "omega" {
284			t.Fatalf("a final line without newline must normalize normally: %#v", results[1])
285		}
286	}
287	
288	// Empty input — and input holding only blank lines — ends quietly: no
289	// results, no diagnostics, exit status 0.
290	func TestNormalizeCLIEmptyOrBlankOnlyInput(t *testing.T) {
291		cases := []struct {
292			name  string
293			input string
294		}{
295			{"completely empty", ""},
296			{"only blank lines", "\n   \n\t\n"},
297		}
298		for _, tc := range cases {
299			t.Run(tc.name, func(t *testing.T) {
300				result := runNormalizeCLI(t, strings.NewReader(tc.input))
301				if result.exitCode != 0 {
302					t.Fatalf("input without logs must exit 0, got %d (stderr: %q)", result.exitCode, result.stderr)
303				}
304				if result.stdout != "" {
305					t.Fatalf("no logs means no results on stdout, got %q", result.stdout)
306				}
307				if result.stderr != "" {
308					t.Fatalf("no logs means no diagnostics on stderr, got %q", result.stderr)
309				}
310			})
311		}
312	}
313	
314	// A stdin read failure before any complete log line is a stream-level
315	// problem, not a bad log: the process exits 2, stderr explains the read
316	// failure with the normalize: prefix, and stdout carries no per-line
317	// results — the failure must not be disguised as one log's field error.
318	func TestNormalizeCLIReadErrorExitsTwo(t *testing.T) {
319		// Reading a directory fails deterministically on the first Read, before
320		// any byte of a log line can arrive.
321		dir, err := os.Open(".")
322		if err != nil {
323			t.Fatalf("opening a directory as failing stdin: %v", err)
324		}
325		defer dir.Close()
326	
327		result := runNormalizeCLI(t, dir)
328	
329		if result.exitCode != 2 {
330			t.Fatalf("a stdin read failure must exit 2, got %d (stderr: %q)", result.exitCode, result.stderr)
331		}
332		if result.stdout != "" {
333			t.Fatalf("no complete log line means no results on stdout, got %q", result.stdout)
334		}
335		if !strings.HasPrefix(result.stderr, "normalize: ") {
336			t.Fatalf("the read failure must be reported with the normalize: prefix, got %q", result.stderr)
337		}
338		if !strings.Contains(strings.ToLower(result.stderr), "read") {
339			t.Fatalf("the diagnostic must identify a read failure, got %q", result.stderr)
340		}
341	}
342	
343	// A duplicate top-level key written with a unicode escape is the same failure
344	// as a literal repeated key. With one such line between legal logs (and a
345	// blank line shifting physical numbers), the CLI must emit per-line JSON
346	// results in order, keep the failure's line number with no event and a reason
347	// that names the field, and still exit 1: trailing valid lines never reset
348	// the status. An escape-only spelling of a standard field is a normal event.
349	func TestNormalizeCLIEscapedDuplicateKeyExitsOne(t *testing.T) {
350		dup := `{"timestamp":"2026-01-02T00:00:00Z","action":"first",` + escKey("action") + `:"second"}`
351		escapedOnly := `{` + escKey("timestamp") + `:"2026-01-02T08:04:05+08:00",` + escKey("action") + `:"ok"}`
352		input := `{"timestamp":"2026-01-02T00:00:00Z","action":"first"}` + "\n" +
353			dup + "\n" +
354			"  \n" +
355			`{"timestamp":"2026-01-02T00:00:02Z","action":"last"}` + "\n" +
356			escapedOnly
357	
358		result := runNormalizeCLI(t, strings.NewReader(input))
359	
360		if result.exitCode != 1 {
361			t.Fatalf("a duplicate-key line must set exit status 1 even with later valid logs, got %d (stderr: %q)",
362				result.exitCode, result.stderr)
363		}
364		if result.stderr != "" {
365			t.Fatalf("per-line failures belong in result records, not stderr, got %q", result.stderr)
366		}
367	
368		results := decodeStdoutResults(t, result.stdout)
369		if len(results) != 4 {
370			t.Fatalf("blank lines produce no output; expected 4 results, got %#v", results)
371		}
372		if results[0]["line"] != float64(1) || results[0]["ok"] != true {
373			t.Fatalf("leading valid log must succeed on line 1: %#v", results[0])
374		}
375		if eventOf(t, results[0])["action"] != "first" {
376			t.Fatalf("line 1 event content mismatch: %#v", results[0])
377		}
378	
379		bad := results[1]
380		if bad["line"] != float64(2) || bad["ok"] != false {
381			t.Fatalf("the escaped duplicate key must fail as line 2: %#v", bad)
382		}
383		if _, exists := bad["event"]; exists {
384			t.Fatalf("a failed line must not carry an event: %#v", bad)
385		}
386		message, ok := bad["error"].(string)
387		if !ok || message == "" {
388			t.Fatalf("the failed line must explain itself: %#v", bad)
389		}
390		if !strings.Contains(strings.ToLower(message), "duplicate") || !strings.Contains(message, "action") {
391			t.Fatalf("error must identify the duplicate action field, got %q", message)
392		}
393		if strings.Contains(strings.ToLower(message), "conflict") {
394			t.Fatalf("a decoded duplicate key must not be reported as an action conflict: %q", message)
395		}
396	
397		if results[2]["line"] != float64(4) || results[2]["ok"] != true {
398			t.Fatalf("the valid log after the blank line must succeed as line 4: %#v", results[2])
399		}
400		if eventOf(t, results[2])["action"] != "last" {
401			t.Fatalf("line 4 event content must survive in order: %#v", results[2])
402		}
403	
404		if results[3]["line"] != float64(5) || results[3]["ok"] != true {
405			t.Fatalf("an escape-only standard field spelling must succeed as line 5: %#v", results[3])
406		}
407		if eventOf(t, results[3])["timestamp"] != "2026-01-02T00:04:05Z" {
408			t.Fatalf("escaped-only names must normalize like literal names: %#v", results[3])
409		}
410	}
