			r := expectCharFailure(t, tc.input, "unpaired", "surrogate")
			msg := r["error"].(string)
			if strings.Contains(msg, "UTF-8") {
				t.Fatalf("unpaired escape must not be reported as UTF-8 corruption, got %q", msg)
			}
		})
	}
